export interface CreatedHeroMemory {
  memoryType: 'origin' | 'discipline' | 'progress'
  rarity: MemoryRarity
  baseStat: MemorySlotSelection | null
  fixedAffixes: [MemorySlotSelection | null, MemorySlotSelection | null]
  randomAffixes: [MemorySlotSelection | null, MemorySlotSelection | null]
}

const MEMORY_NAMES: Record<CreatedHeroMemory['memoryType'], string> = {
  origin: 'Memory of Origin',
  discipline: 'Memory of Discipline',
  progress: 'Memory of Progress',
}

export function buildMemoryEffects(memories: (CreatedHeroMemory | null)[]): EffectInput[] {
  const effects: EffectInput[] = []
  const RANGE_RE = /\(\d+(?:\.\d+)?[–\-]\d+(?:\.\d+)?\)/g
  const resolveModifier = (sel: MemorySlotSelection): string => {
    // Ensure leading + for modifiers stored without it (handles legacy/missing-plus data)
    const mod = /^\d/.test(sel.modifier) ? '+' + sel.modifier : sel.modifier
    if (sel.rolledValue === null) return mod
    const val = Number.isInteger(sel.rolledValue) ? String(sel.rolledValue) : sel.rolledValue.toFixed(2)
    return mod.replace(RANGE_RE, val)
  }
  for (const mem of memories) {
    if (!mem) continue
    const src = MEMORY_NAMES[mem.memoryType] ?? 'Hero Memory'
    const push = (sel: MemorySlotSelection) => effects.push({ text: resolveModifier(sel), source: src })
    if (mem.baseStat) push(mem.baseStat)
    for (const fa of mem.fixedAffixes) { if (fa) push(fa) }
    for (const ra of mem.randomAffixes) { if (ra) push(ra) }
  }
  return effects
}

// Expand the level-scaling "( a / b / c / d / e )" notation in a hero-trait effect string to the value at
// `tierIndex` (0-based). Groups without a slash (plain parentheticals) are left untouched.
const _TRAIT_SLASH_RE = /\(([^()]*\/[^()]*)\)/g
function _expandTraitTier(text: string, tierIndex: number): string {
  return text.replace(_TRAIT_SLASH_RE, (_m, inner: string) => {
    const parts = inner.split('/').map(p => p.trim())
    return parts[Math.min(Math.max(tierIndex, 0), parts.length - 1)] ?? parts[parts.length - 1]
  })
}

// Build the engine `trait_effects` list from the selected hero trait. The base trait emits its chosen
// level's effect lines (+ Artificial Moon at max base level); each selected advanced trait emits its
// tier-expanded lines (tier = the slot level for that unlock tier: 45→slot1, 60→slot2, 75→slot3).
// For traits with a bespoke engine module these feed only the status surface; for generic traits the
// backend resolves them into contributions.
export function buildTraitEffects(
  traitId: string | null,
  traitSlotLevels: number[],
  advancedTraitSelections: string[],
  allTraits: HeroTrait[],
): EffectInput[] {
  if (!traitId) return []
  const trait = allTraits.find(t => t.trait_id === traitId)
  if (!trait) return []
  const out: EffectInput[] = []
  const src = trait.variant_name
  // A DISABLED node is a NEGATIVE slot level (the magnitude is its remembered level); skip disabled tiers.
  const slot = (i: number) => traitSlotLevels?.[i] ?? 1
  const tierEnabled = (i: number) => slot(i) >= 1
  const tierLevel = (i: number) => Math.max(1, Math.min(5, Math.abs(slot(i))))
  if (tierEnabled(0)) {
    const baseLevel = tierLevel(0)
    for (const e of trait.levels?.[baseLevel - 1]?.effects ?? []) out.push({ text: e, source: src })
    if (baseLevel >= 5) for (const e of trait.artificial_moon?.effects ?? []) out.push({ text: e, source: src })
  }
  const picks = new Set(advancedTraitSelections ?? [])
  for (const adv of trait.advanced_traits ?? []) {
    if (!picks.has(adv.name)) continue
    const slotIdx = adv.unlock_level >= 75 ? 3 : adv.unlock_level >= 60 ? 2 : 1
    if (!tierEnabled(slotIdx)) continue
    const tierIdx = tierLevel(slotIdx) - 1
    for (const e of adv.effects ?? []) out.push({ text: _expandTraitTier(e, tierIdx), source: adv.name })
  }
  return out
}

