const PASSIVE_TAGS = new Set(['Aura', 'Spirit Magus', 'Focus'])

export function isPassiveSkillItem(s: SkillItem): boolean {
  return s.skill_tags.some(t => PASSIVE_TAGS.has(t))
}

export function isActiveSkillItem(s: SkillItem): boolean {
  return !isPassiveSkillItem(s) &&
    !s.skill_tags.includes('Support') &&
    !s.description_lines[0]?.startsWith('Supports') &&
    !s.name.includes(':')
}

// Compound tag aliases: support text spelling → canonical skill tag
// ── Trait skill slot (Rosa High Court Chariot — Holy Domain) ──────────────────────
// A canonical slot index for the trait-granted skill's supports, kept clear of the 1-9 active/passive slots.
export const TRAIT_SKILL_SLOT = 10
export const TRAIT_SKILL_ID = 'rosa_holy_domain'
// The Holy Domain trait skill as a support-host (synthesized; deals no damage). Tags gate which supports attach.
export const TRAIT_SKILL_PARENT: EquippedSkill = {
  slot: TRAIT_SKILL_SLOT, item_id: TRAIT_SKILL_ID, name: 'Holy Domain',
  skill_type: 'active_skill', level: 1, skill_tags: ['Spell', 'Area', 'Channeled'],
  description_lines: [], supports: [],
} as unknown as EquippedSkill

/** Invulnerability or Divine Intervention (High Court Chariot) grants the Holy Domain support slot. */
export function traitGrantsSkillSlot(traitId: string | null, picks: string[]): boolean {
  return traitId === 'high_court_chariot'
    && (picks.includes('Invulnerability') || picks.includes('Divine Intervention'))
}

const TAG_ALIASES: Record<string, string> = {
  'Slash Strike': 'Slash-Strike',
}

function parseRequiredTags(phrase: string): string[] {
  let remaining = phrase
  const tags: string[] = []
  const sortedAliases = Object.keys(TAG_ALIASES).sort((a, b) => b.length - a.length)
  while (remaining.length > 0) {
    let matched = false
    for (const alias of sortedAliases) {
      if (remaining.toLowerCase().startsWith(alias.toLowerCase())) {
        tags.push(TAG_ALIASES[alias])
        remaining = remaining.slice(alias.length).trim()
        matched = true
        break
      }
    }
    if (!matched) {
      const m = remaining.match(/^(\S+)\s*(.*)$/)
      if (m) { tags.push(m[1]); remaining = m[2] }
      else break
    }
  }
  return tags
}

function checkTag(tag: string, skillTags: string[], isPassiveSlot: boolean): boolean {
  if (tag.toLowerCase() === 'active') return !isPassiveSlot
  if (tag.toLowerCase() === 'passive') return isPassiveSlot
  return skillTags.some(t => t.toLowerCase() === tag.toLowerCase())
}

// Whether a skill actually deals damage (vs a pure Aura / buff / Focus passive). Used to gate
// "Supports skills that deal damage" supports off non-damaging skills (e.g. an Aura like Electric Conversion).
function skillDealsDamage(skill: { skill_tags: string[] }): boolean {
  const dmgTags = ['attack', 'spell', 'minion', 'summon']
  return skill.skill_tags.some(t => dmgTags.includes(t.toLowerCase()))
}

export function isSupportCompatible(
  support: SkillItem,
  parentSkill: EquippedSkill,
  isPassiveSlot: boolean,
  supportIdx: number,
  isTraitSkillSlot = false   // the Holy Domain trait slot: a Support Skill OR Activation Medium support
): boolean {
  // Tag-based exclusion: certain support tags require the parent to share that tag
  if (support.skill_tags.includes('Spirit Magus') && !parentSkill.skill_tags.includes('Spirit Magus')) return false
  if (support.skill_tags.includes('Summon') && !parentSkill.skill_tags.includes('Summon')) return false
  if (support.skill_tags.includes('Spell') && !support.skill_tags.includes('Attack') &&
      !parentSkill.skill_tags.includes('Spell')) return false
  if (support.skill_tags.includes('Attack') && !support.skill_tags.includes('Spell') &&
      !parentSkill.skill_tags.includes('Attack')) return false

  // Activation Medium: any active skill, slot 1 only — EXCEPT the trait skill slot, which explicitly accepts
  // "a Support Skill or Activation Medium Support Skill" (Rosa Invulnerability / Divine Intervention).
  if (support.skill_tags.includes('Activation Medium')) {
    return isTraitSkillSlot || (!isPassiveSlot && supportIdx === 1)
  }

  // Skill-bound supports (Noble/Magnificent) carry a "<Parent Skill>: <Variant> (Tier)" name and lock to a
  // specific parent skill + slot. ONLY these genuinely-bound types use the colon branch — every skill-bound
  // colon support is noble/magnificent, while "Precise: X" (and other base support_skill colon names) are
  // quality-tier VARIANTS of normal supports. So Precise variants must be matched by their "Supports X"
  // description below (e.g. "Precise: Stand as One" → "Supports Aura Skills"), not hidden as a foreign binding.
  const skillBound = support.skill_type === 'noble_support_skill' || support.skill_type === 'magnificent_support_skill'
  if (skillBound && support.name.includes(':')) {
    const parentPart = support.name.split(':')[0].trim()
    if (parentSkill.name !== parentPart) return false
    const ordinals: [string, number][] = [
      ['first', 1], ['second', 2], ['third', 3], ['fourth', 4], ['fifth', 5],
    ]
    for (const descLine of support.description_lines) {
      if (descLine.includes('Support Skill Slot')) {
        for (const [word, num] of ordinals) {
          if (descLine.toLowerCase().includes(word)) return num === supportIdx
        }
      }
    }
    return true
  }

  // Generic "Supports X Skills" description parsing
  const firstLine = support.description_lines[0] || ''
  if (!firstLine.startsWith('Supports')) return false

  // The "Supports X Skills." requirement is ONLY the sentence up to its first period — the rest of the
  // line is the support's effect text (the importer concatenates the whole description into one line).
  // Without isolating it, the requirement parse choked on trailing effect text (e.g. Jump's "...or Chain
  // Skills. +2 Jumps..." never matched Chain), so most supports were wrongly hidden.
  const clauseMatch = firstLine.match(/^Supports\s+(.+?)\./)
  const raw = (clauseMatch ? clauseMatch[1] : firstLine.replace(/^Supports\s+/, '')).trim()
  if (raw.toLowerCase() === 'any skill' || raw.toLowerCase() === 'any skills') return true
  // "Supports skills that hit enemies / deal damage / summon …" all require an active damage/summon skill —
  // a pure Aura/buff/Focus passive matches none of them, so gate on the skill actually dealing damage. (This
  // is what stops Passivation, Added X Damage, Blind, etc. from showing for an Aura like Electric Conversion.)
  if (/^skills?\s+that/i.test(raw)) return skillDealsDamage(parentSkill)

  const alternatives = raw.split(/\s+or\s+/i)
  return alternatives.some(alt => {
    const andGroups = alt.split(/\s+and\s+/i)
    return andGroups.every(group => {
      const phrase = group.replace(/\s+skills?\s*$/i, '').trim()
      const required = parseRequiredTags(phrase)
      return required.every(tag => checkTag(tag, parentSkill.skill_tags, isPassiveSlot))
    })
  })
}

// Support slot energy costs (index 1-5 within each skill)
const SUPPORT_ACTIVE_COSTS  = [0, 10, 15, 50, 100]
const SUPPORT_PASSIVE_COSTS = [10, 10, 15, 50, 100]

export function getSupportEnergyCost(isPassive: boolean, supportIdx: number): number {
  const costs = isPassive ? SUPPORT_PASSIVE_COSTS : SUPPORT_ACTIVE_COSTS
  return costs[Math.max(0, Math.min(4, supportIdx - 1))]
}

// Per-gear-slot energy contribution (helm/gloves/boots/each 1H = 61; chest/2H = 122)
function gearSlotEnergy(slot: GearSlot | GearSlot[] | null): number {
  if (!slot) return 0
  if (Array.isArray(slot)) return slot.reduce((s, sl) => s + gearSlotEnergy(sl), 0)
  if (slot === 'chest') return 122
  if (slot === 'weapon1' || slot === 'weapon2') return 61  // refined when base_type known
  if (slot === 'helmet' || slot === 'gloves' || slot === 'boots') return 61
  return 0  // amulet, belt, ring1, ring2
}

export function getMaxEnergy(level: number, gear: EquippedGearItem[], effortlessCommand: boolean): number {
  const fromGear = gear.reduce((s, g) => s + gearSlotEnergy(g.slot), 0)
  return 4 + fromGear + Math.min(Math.max(level, 0), 100) + (effortlessCommand ? 1000 : 0)
}

// +1000 Max Energy comes from placing the Effortless Command Ethereal Prism (the engine grants it via the
// core-talent path; this derives the same for the client-side energy-budget display). Threshold-gated at 24 pts.
export function hasEffortlessCommandEnergy(prisms: PlacedPrism[], slots: (TreeSlot | null)[]): boolean {
  return (prisms ?? []).some(p => {
    if (p.kind !== 'ethereal_prism' || p.ethereal?.shortName !== 'Effortless Command') return false
    const ns = slots.find(s => s?.treeName === p.treeName)?.nodeStates ?? {}
    return Object.values(ns).reduce((a, b) => a + (b || 0), 0) >= 24
  })
}

export interface CharacterStatContribution {
  stat: string
  amount: number
  label: string
  text: string
}

// Baseline character stats every character has before gear/talents — Max Life, Max Mana, and
// Max Energy. The engine has no intrinsic base values (derive.py base = 0), so these are injected
// here as 'Base'/'Levels' character contributions.
//   Max Life:   50 base + 13 per level
//   Max Mana:   40 base +  5 per level
//   Max Energy:  4 base +  1 per level (+ gear slots, + Prism)
// NOTE (revisit): base regen is NOT modeled — Life regen over time; Mana 7/s + 1.75%/s. Needs
// regen stats in the engine. Likewise Temporary Life/Mana and Base-Max variants are unmodeled.
export function buildCharacterContributions(
  gear: EquippedGearItem[],
  characterLevel: number,
): CharacterStatContribution[] {
  const contribs: CharacterStatContribution[] = []
  const lvl = Math.min(Math.max(characterLevel, 0), 100)
  // Per-level scaling is per level GAINED — a player starts at level 1 with the base value, so
  // multiply by (level - 1), not level.
  const levelsGained = Math.max(lvl - 1, 0)

  const baseLife = 50 + 13 * levelsGained
  contribs.push({ stat: 'max_life_flat', amount: baseLife, label: 'Base', text: `+${baseLife} Max Life (50 + 13/level)` })

  const baseMana = 40 + 5 * levelsGained
  contribs.push({ stat: 'max_mana_flat', amount: baseMana, label: 'Base', text: `+${baseMana} Max Mana (40 + 5/level)` })

  // Base Evasion = 2 per level gained (Help DB: "Players have 0 Evasion by default. Evasion increased by 2 for
  // every level gained."). Scaled by % increased Evasion via the engine's evasion_flat pool.
  const baseEvasion = 2 * levelsGained
  if (baseEvasion > 0) contribs.push({ stat: 'evasion_flat', amount: baseEvasion, label: 'Base', text: `+${baseEvasion} Evasion (2/level)` })

  contribs.push({ stat: 'max_energy_flat', amount: 4, label: 'Base', text: '+4 Max Energy' })
  const gearE = gear.reduce((s, g) => s + gearSlotEnergy(g.slot), 0)
  if (gearE > 0) contribs.push({ stat: 'max_energy_flat', amount: gearE, label: 'Gear', text: `+${gearE} Max Energy` })
  if (lvl > 0) contribs.push({ stat: 'max_energy_flat', amount: lvl, label: 'Levels', text: `+${lvl} Max Energy` })
  // +1000 Max Energy (Effortless Command) is granted by the engine when that Ethereal Prism is placed — no
  // longer a manual toggle here (it would double-count with the prism's core-talent grant).
  return contribs
}

